
.status-card {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 14px;
  box-shadow: 0 4px 16px rgba(58, 58, 68, 0.1);
  overflow: hidden;
  font-family: var(--font-ui);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.status-card::before {
  content: '';
  display: block;
  height: 3px;
  background: linear-gradient(90deg, var(--c-primary), var(--c-accent));
  transition: background 0.3s ease;
}

.status-card.crisis {
  border-color: color-mix(in srgb, var(--c-ink) 55%, var(--c-border));
  box-shadow: 0 4px 16px rgba(62, 92, 138, 0.18);
}

.status-card.crisis::before {
  background: linear-gradient(90deg, var(--c-ink), var(--c-danger));
}

.header {
  position: relative;
  cursor: pointer;
  user-select: none;
  background: linear-gradient(180deg, var(--c-surface-alt) 0%, var(--c-surface) 100%);
}

.status-card.crisis .header {
  background: linear-gradient(180deg, #f2f5fa 0%, var(--c-surface) 100%);
}

.chevron {
  position: absolute;
  right: 10px;
  top: 10px;
  color: var(--c-text-muted);
  font-size: 0.8rem;
  transition: transform 0.25s ease;
}

.chevron.open {
  transform: rotate(180deg);
}

.expand-area {
  border-top: 1px dashed var(--c-border);
}

.expand-enter-active,
.expand-leave-active {
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.expand-enter-from,
.expand-leave-to {
  opacity: 0;
  transform: translateY(-4px);
}
