
.header-bar {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.meta-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 16px;
  font-size: 0.82rem;
  color: var(--c-text-muted);
}

.meta-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.meta-item i {
  color: var(--c-primary);
  width: 14px;
  text-align: center;
}

.meta-item.loc i {
  color: var(--c-ink);
}

.meta-item.loc {
  color: var(--c-text);
  font-weight: 600;
}

.route-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.route-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 12px;
  border-radius: 999px;
  background: rgba(229, 155, 166, 0.16);
  border: 1px solid rgba(229, 155, 166, 0.42);
  color: var(--c-primary);
  font-weight: 700;
  font-size: 0.85rem;
  white-space: nowrap;
}

.route-badge.crisis {
  background: rgba(62, 92, 138, 0.12);
  border-color: rgba(62, 92, 138, 0.36);
  color: var(--c-ink);
}

.bond {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 180px;
}

.bond-label {
  font-size: 0.78rem;
  color: var(--c-text-muted);
  white-space: nowrap;
}

.bond-label i {
  color: var(--c-accent);
  margin-right: 2px;
}

.bond .bar-track {
  flex: 1;
  height: 8px;
}

.bond-value {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--c-accent);
  min-width: 2.4em;
  text-align: right;
}

.girls-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.girl {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.girl-name {
  font-size: 0.7rem;
  color: var(--c-text-muted);
  text-align: center;
}

.bar-track {
  height: 7px;
  border-radius: 999px;
  background: rgba(229, 155, 166, 0.16);
  overflow: hidden;
}

.bar-track.mini {
  height: 5px;
}

.bar-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--c-primary), var(--c-accent));
  transition: width 0.3s ease;
}

.bar-fill.zero {
  opacity: 0.35;
}

@media (max-width: 600px) {
  .girls-row {
    gap: 5px;
  }

  .bond {
    min-width: 100%;
    margin-top: 2px;
  }
}
